var PACKAGES = {
  A: { label:'Package A — small events', base:4000, hours:4,
       events:['Birthday','Anniversary','Christening','Housewarming','Pre-wedding','Civil wedding','Other'] },
  B: { label:'Package B — creative photoshoot', base:2000, hours:2,
       events:['Debut','Model shoot','Product shoot','Maternity shoot','Other'] }
};
var EXTRA_RATE = 500;
var selectedPkg = 'A';

function peso(n){ return '₱' + n.toLocaleString('en-PH'); }
function pesoPDF(n){ return 'PHP ' + n.toLocaleString('en-PH'); }

function populateEvents(){
  var sel = document.getElementById('f-event');
  sel.innerHTML = '';
  PACKAGES[selectedPkg].events.forEach(function(ev){
    var o = document.createElement('option'); o.value = ev; o.textContent = ev; sel.appendChild(o);
  });
}

function pad2(n){ return n<10 ? '0'+n : ''+n; }

function formatDatePretty(iso){
  if(!iso) return '';
  var d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('en-US', { month:'long', day:'numeric', year:'numeric' });
}
function formatTimePretty(hm){
  if(!hm) return '';
  var parts = hm.split(':');
  var h = parseInt(parts[0],10);
  var ap = h>=12 ? 'PM' : 'AM';
  var h12 = h % 12; if(h12===0) h12 = 12;
  return h12 + ':' + parts[1] + ' ' + ap;
}

function updateEndTime(){
  var start = document.getElementById('f-starttime').value;
  var extra = parseInt(document.getElementById('f-extra').value || '0', 10);
  var totalHours = PACKAGES[selectedPkg].hours + extra;
  var out = document.getElementById('f-endtime');
  if(!start){ out.value=''; return; }
  var parts = start.split(':');
  var d = new Date(2000,0,1, parseInt(parts[0],10), parseInt(parts[1],10));
  d.setHours(d.getHours() + totalHours);
  out.value = formatTimePretty(pad2(d.getHours()%24) + ':' + pad2(d.getMinutes())) + ' (' + totalHours + ' hrs from start)';
}

function updateSummary(){
  var extra = parseInt(document.getElementById('f-extra').value || '0', 10);
  if(extra<0) extra = 0;
  var pkg = PACKAGES[selectedPkg];
  var extraCost = extra * EXTRA_RATE;
  var total = pkg.base + extraCost;
  var down = Math.round(total/2);
  var balance = total - down;
  document.getElementById('s-pkg-label').textContent = pkg.label + ' — ' + pkg.hours + ' hrs';
  document.getElementById('s-base').textContent = peso(pkg.base);
  document.getElementById('s-extra-label').textContent = 'Additional hours (' + extra + ')';
  document.getElementById('s-extra').textContent = peso(extraCost);
  document.getElementById('s-total').textContent = peso(total);
  document.getElementById('s-down').textContent = peso(down);
  document.getElementById('s-balance').textContent = peso(balance);
  updateEndTime();
}

document.querySelectorAll('.pkg-opt').forEach(function(el){
  el.addEventListener('click', function(){
    document.querySelectorAll('.pkg-opt').forEach(function(o){ o.classList.remove('selected'); });
    el.classList.add('selected');
    selectedPkg = el.getAttribute('data-pkg');
    populateEvents();
    updateSummary();
  });
});
document.getElementById('f-extra').addEventListener('input', updateSummary);

function checkWeekdayWarn(){
  var d = document.getElementById('f-eventdate').value;
  var t = document.getElementById('f-starttime').value;
  var warn = document.getElementById('weekday-warn');
  if(d && t){
    var day = new Date(d + 'T00:00:00').getDay();
    var isWeekday = day>=1 && day<=5;
    var hh = parseInt(t.split(':')[0],10);
    warn.style.display = (isWeekday && hh<17) ? 'block' : 'none';
  } else {
    warn.style.display = 'none';
  }
}
function onStartTimeChange(){ updateSummary(); checkWeekdayWarn(); }
function onEventDateChange(){ checkWeekdayWarn(); }

flatpickr('#f-eventdate', {
  dateFormat:'Y-m-d', altInput:true, altFormat:'l, F j, Y', minDate:'today',
  disableMobile:true, onChange:onEventDateChange
});

function populateStartTimes(){
  var sel = document.getElementById('f-starttime');
  for(var h=0; h<24; h++){
    for(var m=0; m<60; m+=30){
      var val = pad2(h) + ':' + pad2(m);
      var o = document.createElement('option');
      o.value = val; o.textContent = formatTimePretty(val);
      sel.appendChild(o);
    }
  }
}
populateStartTimes();
document.getElementById('f-starttime').addEventListener('change', onStartTimeChange);

populateEvents();
updateSummary();

// signature pad
var canvas = document.getElementById('sigpad');
var ctx = canvas.getContext('2d');
var drawing = false, hasSig = false;
function resizeCanvas(){
  var ratio = window.devicePixelRatio || 1;
  var rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * ratio;
  canvas.height = rect.height * ratio;
  ctx.scale(ratio, ratio);
  ctx.lineWidth = 2; ctx.lineCap = 'round'; ctx.strokeStyle = '#241C15';
}
resizeCanvas();
window.addEventListener('resize', function(){
  var data = hasSig ? canvas.toDataURL() : null;
  resizeCanvas();
  if(data){ var img = new Image(); img.onload=function(){ ctx.drawImage(img,0,0,canvas.width,canvas.height); }; img.src = data; }
});
function pos(e){
  var rect = canvas.getBoundingClientRect();
  var p = e.touches ? e.touches[0] : e;
  return { x: p.clientX - rect.left, y: p.clientY - rect.top };
}
function start(e){ drawing = true; hasSig = true; var p = pos(e); ctx.beginPath(); ctx.moveTo(p.x,p.y); e.preventDefault(); }
function move(e){ if(!drawing) return; var p = pos(e); ctx.lineTo(p.x,p.y); ctx.stroke(); e.preventDefault(); }
function end(){ drawing = false; }
canvas.addEventListener('mousedown', start);
canvas.addEventListener('mousemove', move);
window.addEventListener('mouseup', end);
canvas.addEventListener('touchstart', start);
canvas.addEventListener('touchmove', move);
canvas.addEventListener('touchend', end);
document.getElementById('sig-clear').addEventListener('click', function(){
  ctx.clearRect(0,0,canvas.width,canvas.height); hasSig = false;
});

function validate(){
  var ok = true;
  var reqs = [
    ['f-name'], ['f-contact'], ['f-location'], ['f-eventdate'], ['f-starttime'], ['f-pax']
  ];
  reqs.forEach(function(r){
    var el = document.getElementById(r[0]);
    var field = el.closest('.field');
    if(!el.value){ field.classList.add('invalid'); ok = false; }
    else{ field.classList.remove('invalid'); }
  });
  var sigField = document.getElementById('sigpad').closest('.field');
  var sigErr = document.getElementById('sig-err');
  if(!hasSig){ sigErr.style.display = 'block'; ok = false; } else { sigErr.style.display = 'none'; }
  return ok;
}

document.getElementById('gen-pdf').addEventListener('click', function(){
  var status = document.getElementById('status');
  status.className = 'status-msg';
  if(!document.getElementById('f-agree').checked){
    status.textContent = 'Please check the agreement box before generating your PDF.';
    status.classList.add('bad','show');
    return;
  }
  if(!validate()){
    status.textContent = 'A few fields still need your input — check the highlighted ones above.';
    status.classList.add('bad','show');
    return;
  }
  var pkg = PACKAGES[selectedPkg];
  var extra = parseInt(document.getElementById('f-extra').value || '0', 10);
  var total = pkg.base + extra*EXTRA_RATE;
  var down = Math.round(total/2);
  var balance = total - down;

  var jsPDF = window.jspdf.jsPDF;
  var doc = new jsPDF({ unit:'pt', format:'a4' });
  var left = 56, width = 483;
  var genDate = new Date().toISOString().slice(0,10);

  var logoSize = 46, logoY = 40;
  doc.addImage('data:image/png;base64,', 'PNG', left, logoY, logoSize, logoSize);
  var textX = left + logoSize + 16;
  doc.setFont('helvetica','bold'); doc.setFontSize(18); doc.setTextColor(20);
  doc.text('GP Studio PH', textX, logoY + 20);
  doc.setFont('helvetica','normal'); doc.setFontSize(11); doc.setTextColor(90);
  doc.text('Photography Service Agreement', textX, logoY + 40);
  doc.setTextColor(20);

  var y = logoY + logoSize + 26;
  doc.setFont('helvetica','normal'); doc.setFontSize(10); doc.setTextColor(90);
  doc.text('Date generated: ' + formatDatePretty(genDate), left, y); y += 24;
  doc.setTextColor(20);

  function sectionHeader(text){
    doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.setTextColor(20);
    doc.text(text, left, y); y += 16;
  }
  function row(label, value){
    doc.setFont('helvetica','bold'); doc.setFontSize(10);
    doc.text(label, left, y);
    doc.setFont('helvetica','normal'); doc.setFontSize(10);
    doc.text(String(value || '—'), left + 160, y);
    y += 18;
  }

  sectionHeader('Client details');
  row('Full name', document.getElementById('f-name').value);
  row('Contact #', document.getElementById('f-contact').value);
  row('Pax', document.getElementById('f-pax').value);
  y += 8;

  sectionHeader('Event details');
  row('Event', document.getElementById('f-event').value);
  row('Location', document.getElementById('f-location').value);
  row('Event date', formatDatePretty(document.getElementById('f-eventdate').value));
  row('Start time', formatTimePretty(document.getElementById('f-starttime').value));
  row('Estimated end time', document.getElementById('f-endtime').value);
  y += 8;

  sectionHeader('Package & pricing');
  row('Package', pkg.label);
  row('Base coverage', pkg.hours + ' hours — ' + pesoPDF(pkg.base));
  row('Additional hours', extra + ' hr(s) x ' + pesoPDF(EXTRA_RATE));
  row('Total', pesoPDF(total));
  row('Downpayment (50%)', pesoPDF(down));
  row('Balance', pesoPDF(balance));
  y += 8;

  sectionHeader('Terms');
  doc.setFont('helvetica','normal'); doc.setFontSize(10); doc.setTextColor(60);
  var terms = 'Photography only — videography is not included. Unlimited photos are taken during coverage; ' +
    'RAW and enhanced photos are uploaded to a Google Drive folder and provided within 1–3 days. ' +
    'A 50% downpayment is required to confirm this booking, with the remaining balance due on the day of the event, ' +
    'upon completion of service. Out-of-town shoots are not included in the starting rate and may vary depending on the location.';
  var lines = doc.splitTextToSize(terms, width);
  doc.text(lines, left, y); y += lines.length*13 + 20;
  doc.setTextColor(20);

  doc.setFont('helvetica','bold'); doc.setFontSize(12); doc.text('Client signature', left, y); y += 8;
  var sigData = canvas.toDataURL('image/png');
  doc.addImage(sigData, 'PNG', left, y, 220, 70);
  y += 82;
  doc.setFont('helvetica','normal'); doc.setFontSize(10); doc.setTextColor(90);
  doc.text('Signed: ' + document.getElementById('f-name').value + '   Date: ' + formatDatePretty(genDate), left, y);

  doc.save('GP-Studio-PH-Agreement.pdf');
  status.textContent = 'Your agreement downloaded. See you at the shoot!';
  status.classList.add('ok','show');
});

/* ===================================================================
   GP Studio PH — app shell: portfolio, interactions, PWA
   =================================================================== */
(function(){
  var $=function(s,r){return (r||document).querySelector(s)}, $$=function(s,r){return Array.prototype.slice.call((r||document).querySelectorAll(s))};
  var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  function tap(){ if(navigator.vibrate) navigator.vibrate(8); }
  var tt; function toast(msg){ var t=$('#toast'); t.textContent=msg; t.classList.add('show'); clearTimeout(tt); tt=setTimeout(function(){t.classList.remove('show')},3200); }

  /* ---------- Portfolio: edit this list ----------
     Put your photos in a /portfolio folder and set src, e.g. src:'portfolio/birthday-01.jpg'.
     Tiles with an empty src show a placeholder frame. r = aspect ratio of the tile. */
  var WORK=[
    {t:'Golden hour birthday',c:'Events',r:'4/5',src:''},
    {t:'Christening day',c:'Events',r:'1/1',src:''},
    {t:'Pre-wedding session',c:'Weddings',r:'3/4',src:''},
    {t:'Civil wedding',c:'Weddings',r:'4/3',src:''},
    {t:'Debut portraits',c:'Portraits',r:'3/4',src:''},
    {t:'Maternity glow',c:'Portraits',r:'4/5',src:''},
    {t:'Model shoot',c:'Portraits',r:'1/1',src:''},
    {t:'Product flat lay',c:'Products',r:'4/3',src:''},
    {t:'Housewarming',c:'Events',r:'3/4',src:''},
    {t:'Anniversary dinner',c:'Events',r:'4/5',src:''}
  ];
  var cats=['All'].concat(WORK.map(function(w){return w.c}).filter(function(c,i,a){return a.indexOf(c)===i}));
  var cur='All', list=WORK, li=0;

  /* aperture line-art used in hero + empty tiles */
  function irisMarkup(){
    var o='<circle cx="100" cy="100" r="96" fill="none" stroke="currentColor" stroke-width=".8"/><circle cx="100" cy="100" r="78" fill="none" stroke="currentColor" stroke-width=".4" opacity=".6"/><g>', pts=[];
    for(var k=0;k<6;k++){
      var a=(60*k-90)*Math.PI/180, b=(60*k-90+78)*Math.PI/180;
      var px=100+34*Math.cos(a), py=100+34*Math.sin(a);
      pts.push(px.toFixed(1)+','+py.toFixed(1));
      o+='<line x1="'+px.toFixed(1)+'" y1="'+py.toFixed(1)+'" x2="'+(100+96*Math.cos(b)).toFixed(1)+'" y2="'+(100+96*Math.sin(b)).toFixed(1)+'" stroke="currentColor" stroke-width=".8"/>';
    }
    return o+'</g><polygon class="hole" points="'+pts.join(' ')+'" fill="none" stroke="currentColor" stroke-width=".8"/>';
  }
  function fillIris(r){ $$('[data-iris]',r).forEach(function(s){ if(!s.firstChild) s.innerHTML=irisMarkup(); }); }
  fillIris();

  function visual(w,i){
    if(w.src) return '<img src="'+w.src+'" alt="'+w.t+'" loading="lazy">';
    var h=28+(i*13)%30;
    return '<div class="ph" style="background:linear-gradient(155deg,hsl('+h+' 9% 22%),hsl('+h+' 8% 8%))"><svg viewBox="0 0 200 200" data-iris aria-hidden="true"></svg></div>';
  }
  function renderChips(){
    $('#filters').innerHTML=cats.map(function(c){return '<button class="chip" role="tab" type="button" aria-selected="'+(c===cur)+'" data-c="'+c+'">'+c+'</button>'}).join('');
  }
  function renderGallery(){
    list=WORK.filter(function(w){return cur==='All'||w.c===cur});
    var g=$('#gallery');
    g.innerHTML=list.map(function(w,i){
      return '<button class="tile" type="button" data-i="'+i+'" style="aspect-ratio:'+w.r+';animation-delay:'+(reduce?0:i*55)+'ms" aria-label="View '+w.t+'">'+visual(w,i)+'<span class="cap">'+w.t+'<small>'+w.c+'</small></span></button>';
    }).join('');
    fillIris(g);
  }
  $('#filters').addEventListener('click',function(e){
    var b=e.target.closest('.chip'); if(!b) return;
    cur=b.getAttribute('data-c'); tap(); renderChips(); renderGallery();
  });
  renderChips(); renderGallery();

  /* ---------- Live portfolio from the upload database (falls back to the sample tiles above) ---------- */
  var EV={birthday:'Birthday',wedding:'Wedding',christening:'Christening',anniversary:'Anniversary',debut:'Debut',maternity:'Maternity',portrait:'Portrait',product:'Product',other:'Other'};
  fetch('/api/portfolio').then(function(r){return r.json()}).then(function(d){
    if(!d.items||!d.items.length) return;
    WORK=d.items.map(function(it){var n=EV[it.category]||it.category; return {t:n+' session',c:n,r:it.r||'4/5',src:it.url}});
    cats=['All'].concat(WORK.map(function(w){return w.c}).filter(function(c,i,a){return a.indexOf(c)===i}));
    cur='All'; renderChips(); renderGallery();
  }).catch(function(){});

  /* lightbox */
  var lb=$('#lb'), fig=$('#lb-fig');
  function show(i){
    li=(i+list.length)%list.length; var w=list[li];
    fig.innerHTML=visual(w,li)+'<figcaption>'+w.t+'<small>'+w.c+' · '+(li+1)+' of '+list.length+'</small></figcaption>';
    fillIris(fig);
  }
  $('#gallery').addEventListener('click',function(e){
    var t=e.target.closest('.tile'); if(!t) return;
    show(+t.getAttribute('data-i')); lb.showModal(); tap();
  });
  $('#lb-x').onclick=function(){lb.close()};
  $('#lb-prev').onclick=function(){show(li-1)};
  $('#lb-next').onclick=function(){show(li+1)};
  lb.addEventListener('click',function(e){ if(e.target===lb) lb.close(); });
  lb.addEventListener('keydown',function(e){ if(e.key==='ArrowLeft') show(li-1); if(e.key==='ArrowRight') show(li+1); });
  var sx=null;
  lb.addEventListener('pointerdown',function(e){sx=e.clientX});
  lb.addEventListener('pointerup',function(e){ if(sx===null) return; var d=e.clientX-sx; sx=null; if(Math.abs(d)>60) show(li+(d<0?1:-1)); });

  /* ---------- Hero aperture: reacts to scroll and pointer ---------- */
  var iris=$('#hero-iris'), px=0;
  function irisUpdate(){
    var y=Math.min(scrollY,900);
    iris.style.setProperty('--rot',(y*.06+px*14).toFixed(1));
    iris.style.setProperty('--open',(1+y/1400).toFixed(2));
  }
  if(!reduce){
    addEventListener('scroll',irisUpdate,{passive:true});
    addEventListener('pointermove',function(e){ if(e.pointerType==='mouse'){ px=e.clientX/innerWidth-.5; irisUpdate(); } },{passive:true});
    irisUpdate();
  }
  addEventListener('scroll',function(){ $('.top').classList.toggle('stuck',scrollY>12); },{passive:true});

  /* ---------- Scroll spy: dock + services sub-nav ---------- */
  function spy(ids,sel,attr,cls){
    var io=new IntersectionObserver(function(es){
      es.forEach(function(en){
        if(!en.isIntersecting) return;
        $$(sel).forEach(function(a){ a.classList.toggle(cls, a.getAttribute(attr)===en.target.id || a.getAttribute(attr)==='#'+en.target.id); });
      });
    },{rootMargin:'-45% 0px -50% 0px'});
    ids.forEach(function(id){ var el=document.getElementById(id); if(el) io.observe(el); });
  }
  spy(['home','portfolio','services'],'#dock a[data-s]','data-s','on');
  spy(['rates','availability','book','pay','sign'],'#subnav a','href','on');

  /* ---------- Packages: pick a card, jump to the form ---------- */
  function syncPkg(){ $$('.pkg-card').forEach(function(c){ c.classList.toggle('on',c.getAttribute('data-pick')===selectedPkg); }); }
  $$('.pkg-card').forEach(function(c){
    c.addEventListener('click',function(e){
      if(!e.target.closest('button')) return;
      var p=c.getAttribute('data-pick'); $('.pkg-opt[data-pkg="'+p+'"]').click(); tap();
      toast('Package '+p+' selected');
      setTimeout(function(){ document.getElementById('book').scrollIntoView({behavior:reduce?'auto':'smooth'}); },350);
    });
  });
  $$('.pkg-opt').forEach(function(o){ o.addEventListener('click',function(){ syncPkg(); tap(); }); });

  /* ---------- Steppers + price flash ---------- */
  $$('.stepper button').forEach(function(b){
    b.addEventListener('click',function(){
      var inp=document.getElementById(b.getAttribute('data-for')), min=parseInt(inp.min||'0',10);
      var v=(parseInt(inp.value,10)||(min===1?0:0))+parseInt(b.getAttribute('data-step'),10);
      inp.value=Math.max(min,v); inp.dispatchEvent(new Event('input',{bubbles:true})); tap();
    });
  });
  ['s-total','s-down','s-balance'].forEach(function(id){
    var el=document.getElementById(id);
    new MutationObserver(function(){ el.classList.remove('bump'); void el.offsetWidth; el.classList.add('bump'); }).observe(el,{childList:true,characterData:true,subtree:true});
  });
  /* on a failed submit, bring the first problem into view */
  $('#gen-pdf').addEventListener('click',function(){
    setTimeout(function(){ var bad=$('.field.invalid'); if(bad) bad.scrollIntoView({block:'center',behavior:reduce?'auto':'smooth'}); },60);
  });

  /* ---------- Not installable: remove any service worker/cache left by earlier versions ---------- */
  if('serviceWorker' in navigator) navigator.serviceWorker.getRegistrations().then(function(rs){ rs.forEach(function(r){ r.unregister(); }); }).catch(function(){});
  if(window.caches) caches.keys().then(function(ks){ ks.forEach(function(k){ caches.delete(k); }); }).catch(function(){});
})();
